glsl3.vert:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};

in vec3 a_position;
in vec4 a_color;
out vec4 v_color;

#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif

void main () {
  vec4 pos = vec4(a_position, 1);
  pos = cc_matViewProj * pos;

  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif

  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;

in vec4 v_color;

#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif

uniform PROPERTIES {
  vec4 u_vfxColor;
  vec4 u_cardMaskCenterHalf;
  vec4 u_cardMaskParams;
  vec4 u_quadEdgeFade;
  float u_vertRayLength;
  float u_vertRayWidth;
  float u_horizRayLength;
  float u_horizRayWidth;
  float u_aspectRatio;
  float u_internalScale;
  float u_globalOpacity;
  float u_starIntensity;
  float u_coreBrightness;
  float u_coreDecay;
  float u_burstStrength;
  float u_godRayMix;
  float u_blurWeight;
  float u_blurDecay;
  float u_exposure;
  float u_profileCurve;
  float u_tipRoundness;
  float u_cornerRoundness;
  float u_lpPower;
  float u_blendMode;
};

vec2 toPolarSpace(vec2 uv01) {
  vec2 uv = (uv01 - vec2(0.5)) * u_internalScale;
  uv.y *= u_aspectRatio;
  return uv;
}

float quadEdgeFade(vec2 uv01) {
  vec2 dist = abs(uv01 - vec2(0.5)) * 2.0;
  float radial = length(dist);
  float axial = max(dist.x, dist.y);
  float axialMix = clamp(u_quadEdgeFade.z, 0.0, 1.0);
  float metric = mix(radial, axial, axialMix);
  float fadeStart = max(0.0, u_quadEdgeFade.x);
  float fadeEnd = max(fadeStart + 0.001, u_quadEdgeFade.y);
  return 1.0 - smoothstep(fadeStart, fadeEnd, metric);
}

float sdRoundedBox(vec2 p, vec2 halfSize, float radius) {
  vec2 r = vec2(max(radius, 0.0));
  vec2 q = abs(p) - halfSize + r;
  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r.x;
}

float cardRegionOpacity(vec2 uv01) {
  vec2 center = u_cardMaskCenterHalf.xy;
  vec2 halfSize = max(u_cardMaskCenterHalf.zw, vec2(0.0001));
  float cornerR = max(u_cardMaskParams.x, 0.0);
  float featherIn = max(u_cardMaskParams.y, 0.0001);
  float featherOut = max(u_cardMaskParams.z, 0.0001);
  float interiorOpacity = clamp(u_cardMaskParams.w, 0.0, 1.0);

  float maxCorner = max(0.0001, min(halfSize.x, halfSize.y) - 0.0001);
  cornerR = min(cornerR, maxCorner);

  float sd = sdRoundedBox(uv01 - center, halfSize, cornerR);
  float exterior = smoothstep(-featherIn, featherOut, sd);
  return mix(interiorOpacity, 1.0, exterior);
}

float smin(float a, float b, float k) {
  float h = clamp(0.5 + 0.5 * (b - a) / max(k, 0.0001), 0.0, 1.0);
  return mix(b, a, h) - k * h * (1.0 - h);
}

float widthProfile(float t) {
  float widthT = clamp(1.0 - t, 0.0, 1.0);
  return max(pow(widthT, u_profileCurve) + u_tipRoundness, 0.0001);
}

float computeArmDistLp(
  float along, float across,
  float rayLen, float rayWid,
  float p
) {
  float gate = step(0.001, rayLen);
  float lSafe = max(rayLen, 0.0001);
  float wSafe = max(rayWid, 0.0001);
  float t = abs(along) / lSafe;
  float wProf = wSafe * widthProfile(t);
  float alongNorm = abs(along) / lSafe;
  float acrossNorm = abs(across) / wProf;
  float d = pow(pow(alongNorm, p) + pow(acrossNorm, p), 1.0 / p);
  return mix(100000.0, d, gate);
}

float computeArmDistL1(
  float along, float across,
  float rayLen, float rayWid
) {
  float gate = step(0.001, rayLen);
  float lSafe = max(rayLen, 0.0001);
  float wSafe = max(rayWid, 0.0001);
  float t = abs(along) / lSafe;
  float wProf = wSafe * widthProfile(t);
  float alongNorm = abs(along) / lSafe;
  float acrossNorm = abs(across) / wProf;
  float d = alongNorm + acrossNorm;
  return mix(100000.0, d, gate);
}

float computeUnifiedDistLp(vec2 uv) {
  float ax = abs(uv.x);
  float ay = abs(uv.y);
  float p = max(u_lpPower, 1.0);
  float dHoriz = computeArmDistLp(ax, ay, u_horizRayLength, u_horizRayWidth, p);
  float dVert = computeArmDistLp(ay, ax, u_vertRayLength, u_vertRayWidth, p);
  return smin(dHoriz, dVert, u_cornerRoundness);
}

float computeUnifiedDistL1(vec2 uv) {
  float ax = abs(uv.x);
  float ay = abs(uv.y);
  float dHoriz = computeArmDistL1(ax, ay, u_horizRayLength, u_horizRayWidth);
  float dVert = computeArmDistL1(ay, ax, u_vertRayLength, u_vertRayWidth);
  return min(dHoriz, dVert);
}

vec3 computeUnifiedGlow(float dStar) {
  float damp = 1.0 / (1.0 + u_burstStrength * 0.45 + u_starIntensity * 0.1);
  float inner = exp(-dStar * u_coreDecay) * u_coreBrightness * damp;
  float outer = exp(-dStar * u_coreDecay * 0.25) * u_burstStrength * 0.2 * damp;
  return u_vfxColor.rgb * (inner + outer) * u_starIntensity;
}

vec3 getRawStarburst(vec2 uv01) {
  float dStar = computeUnifiedDistLp(toPolarSpace(uv01));
  return computeUnifiedGlow(dStar);
}

vec3 getRawStarburstFast(vec2 uv01) {
  float dStar = computeUnifiedDistL1(toPolarSpace(uv01));
  return computeUnifiedGlow(dStar);
}

vec3 getGodRays(vec2 uv01) {
  vec2 center = vec2(0.5);
  vec2 delta = uv01 - center;
  vec2 stepDir = delta / float(20) * u_blurWeight;
  vec3 accum = vec3(0.0);
  float decay = 1.0;
  vec2 sampleUV = uv01;
  for (int i = 0; i < 20; ++i) {
    sampleUV -= stepDir;
    accum += getRawStarburstFast(sampleUV) * decay;
    decay *= u_blurDecay;
  }
  return (accum / float(20)) * u_exposure;
}

void main () {
  #if USE_TEXTURE
  vec2 uv = v_uv0;
  #else
  vec2 uv = vec2(0.5);
  #endif

  float quadFade = quadEdgeFade(uv);
  float overlay = clamp(u_globalOpacity, 0.0, 1.0) * quadFade * v_color.a;
  if (overlay <= 0.0) {
    gl_FragColor = vec4(0.0);
    return;
  }

  vec3 star = getRawStarburst(uv);
  float cardComp = cardRegionOpacity(uv);

  vec3 godPart = vec3(0.0);
  if (u_godRayMix > 0.0) {
    godPart = getGodRays(uv) * u_godRayMix;
  }
  vec3 starPart = star * cardComp;
  vec3 flame = godPart + starPart;
  flame = flame / (1.0 + flame * 0.04);
  flame *= v_color.rgb;

  float mode = u_blendMode;
  vec3 srcRgb = flame;
  if (mode >= 1.5) {
    vec3 dodgeSrc = clamp(flame, 0.0, 0.999);
    dodgeSrc = dodgeSrc / max(vec3(1.0) - dodgeSrc, vec3(0.02));
    srcRgb = min(dodgeSrc, vec3(16.0));
  }

  gl_FragColor = vec4(srcRgb * overlay, overlay);
}

